import{_ as r,C as i,o as t,c,a2 as a,b as l,w as o,a as s,E as h,a3 as n}from"./chunks/framework.DZUUNQ77.js";const m=JSON.parse('{"title":"Replace*MethodProxy · 参数改写代理族","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/method-proxy-replace.md","filePath":"reference/client/method-proxy-replace.md","lastUpdated":1784063681000}'),p={name:"reference/client/method-proxy-replace.md"};function E(k,e,u,P,g,x){const d=i("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="replace-methodproxy-·-参数改写代理族" tabindex="-1">Replace*MethodProxy · 参数改写代理族 <a class="header-anchor" href="#replace-methodproxy-·-参数改写代理族" aria-label="Permalink to &quot;Replace*MethodProxy · 参数改写代理族&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/tree/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/hook/base" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/hook/base/</code></a>（<code>ReplaceCallingPkgMethodProxy</code>/<code>ReplaceLastPkgMethodProxy</code>/<code>ReplaceSequencePkgMethodProxy</code>/<code>ReplaceSpecPkgMethodProxy</code>/<code>ReplaceLastUidMethodProxy</code>/<code>ReplaceUidMethodProxy</code> 等多个文件）</p></div><p><code>Replace*MethodProxy</code> 是一族现成的 <a href="./method-proxy"><code>MethodProxy</code></a> 子类，专门做一件事：<strong>把系统服务方法参数里的包名 / UID 改成虚拟环境的值</strong>。它们继承自 <a href="./method-proxy-static"><code>StaticMethodProxy</code></a>，是 48 个服务代理里复用率最高的一族。</p><h2 id="为什么需要改参数" tabindex="-1">为什么需要改参数 <a class="header-anchor" href="#为什么需要改参数" aria-label="Permalink to &quot;为什么需要改参数&quot;">​</a></h2><p>虚拟 App 调用 <code>getPackageInfo(&quot;com.target&quot;)</code>、<code>startService(intent)</code> 时，参数里带的包名 / UID 是虚拟 App 自己的。但系统服务按真实包名查不到虚拟安装的副本。所以 hook 要在调用前把参数替换：</p><ul><li>包名 → 虚拟 App 在虚拟 PMS 注册的包名（或宿主包名，视场景）。</li><li>UID → 虚拟 uid（<code>VUid</code>）。</li></ul><h2 id="族成员" tabindex="-1">族成员 <a class="header-anchor" href="#族成员" aria-label="Permalink to &quot;族成员&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>改什么</th><th>典型场景</th></tr></thead><tbody><tr><td><code>ReplaceCallingPkgMethodProxy</code></td><td>改 <code>callingPkg</code>（调用方包名）</td><td>App 申明「我是谁」的方法</td></tr><tr><td><code>ReplaceLastPkgMethodProxy</code></td><td>改<strong>末位</strong> <code>String</code> 包名参数</td><td>参数末尾带包名的方法</td></tr><tr><td><code>ReplaceSequencePkgMethodProxy</code></td><td>改<strong>第 N 位</strong>包名参数</td><td>多包名参数按序定位</td></tr><tr><td><code>ReplaceSpecPkgMethodProxy</code></td><td>改<strong>指定</strong>包名参数</td><td>按方法签名精确定位</td></tr><tr><td><code>ReplaceLastUidMethodProxy</code></td><td>改<strong>末位</strong> <code>int</code> uid 参数</td><td>带 uid 的查询</td></tr><tr><td><code>ReplaceUidMethodProxy</code></td><td>改 uid 参数</td><td>通用 uid 替换</td></tr></tbody></table><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>子类只要给方法名，不用写 <code>call</code> 逻辑：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addMethodProxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ReplaceLastPkgMethodProxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getPackageInfo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>注入时由基类在 <code>beforeCall</code> 阶段完成替换，原方法继续执行——这样既改了参数又不改变方法语义。</p><h2 id="参数改写族调用流" tabindex="-1">参数改写族调用流 <a class="header-anchor" href="#参数改写族调用流" aria-label="Permalink to &quot;参数改写族调用流&quot;">​</a></h2>',13)),(t(),l(n,null,{default:o(()=>[h(d,{id:"mermaid-128",class:"mermaid",graph:"flowchart%20LR%0A%20%20CALL%5B%22%E7%B3%BB%E7%BB%9F%E6%96%B9%E6%B3%95%E8%B0%83%E7%94%A8%3Cbr%2F%3E(%E7%9C%9F%E5%8C%85%E5%90%8D%2F%E7%9C%9F%20uid)%22%5D%20--%3E%20BC%5B%22beforeCall%22%5D%0A%20%20BC%20--%3E%20RPU%5B%22MethodParameterUtils%3Cbr%2F%3E%E6%9B%BF%E6%8D%A2%E5%8C%85%E5%90%8D%2Fuid%22%5D%0A%20%20RPU%20--%3E%20CALLM%5B%22call%20%E6%94%BE%E8%A1%8C%E5%8E%9F%E6%96%B9%E6%B3%95%22%5D%0A%20%20CALLM%20--%3E%20SSV%5B%22%E7%9C%9F%E5%AE%9E%E7%B3%BB%E7%BB%9F%E6%9C%8D%E5%8A%A1%3Cbr%2F%3E(%E6%8C%89%E8%99%9A%E6%8B%9F%E8%BA%AB%E4%BB%BD%E6%9F%A5%E8%AF%A2)%22%5D%0A%20%20SSV%20--%3E%20AC%5B%22afterCall%22%5D%0A%20%20AC%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./method-proxy"><code>MethodProxy</code></a>：基类。</li><li><a href="./hook-utils"><code>MethodParameterUtils</code></a>：底层参数替换工具。</li><li><a href="./method-proxy-static"><code>StaticMethodProxy</code></a>：父类。</li><li><a href="./../../features/service-hook">系统服务 Hook</a>。</li></ul>',2))])}const B=r(p,[["render",E]]);export{m as __pageData,B as default};
